style.css:
@-moz-document domain("youtube.com") {
/* Whole progress container background */
  .ytp-progress-bar-container {
    background-color: #1e1e1e !important;
  }

  /* Buffered portion (grey part that shows what’s loaded) */
  .ytp-load-progress {
    background-color: #3c3c3c !important;
  }

  /* Played progress — replaces the red line */
  .ytp-play-progress.ytp-swatch-background-color {
    background-color: #6f8ec7 !important; /* Hollow Knight blue */
    box-shadow: 0 0 6px #6f8ec7 !important;
  }

  /* Scrubber knob */
  .ytp-scrubber-button {
    background-color: #b0c4de !important;
    border-radius: 50% !important;
    width: 13px !important;
    height: 13px !important;
  }
}
